/*
 * SENDING CHECK-INS (DBU-10). A check-in goes when all of these hold: it is shared, still
 * 'scheduled', its sendsAt has come, and its plan is active (a paused or finished plan sends
 * nothing; it goes once the plan is active again). sendsAt is 09:00 Paris on its day; this runs
 * hourly at :05, so one shared late in the day still goes that day rather than tomorrow.
 *
 * Safe to run twice: each check-in is CLAIMED ('sent', sentAt) before its email, and given back
 * ('scheduled') if the email fails, so the next run tries again and nothing goes twice.
 * With no mailer or no appUrl secret nothing is claimed: a check-in nobody was told about would
 * sit on Home unnoticed. A learner who turned emails off (emailOptOutAt) gets none: it is still
 * sent, and waits on her Home. Plain text; logs carry counts, never an address.
 * Answers {sent, mailed, unsent}: unsent are due but left for the next run.
 * A filter takes one key, so the plans are matched after the query.
 */
(async () => {
  let sent = 0;
  let mailed = 0;
  let unsent = 0;
  try {
    const R = Noodl.Records;
    const q = (c, where) => R.query(c, where, { limit: 1000, plain: true });
    const secret = (name) => {
      const s = globalThis._noodl_get_secret ? globalThis._noodl_get_secret(name) : null;
      return s && s.found ? String(s.value) : '';
    };
    const send = typeof globalThis._noodl_send_email === 'function' ? globalThis._noodl_send_email : null;
    const appUrl = secret('appUrl').replace(/\/+$/, '');
    const now = Date.now();

    const plans = await q('Plan', { status: { equalTo: 'active' } });
    const planIds = plans.map((p) => p.objectId);
    const due = planIds.length
      ? (await q('Step', { kind: { equalTo: 'checkin' } }))
        .filter((s) => planIds.includes(s.plan) && s.shared === true && s.status === 'scheduled' && s.sendsAt && Date.parse(s.sendsAt) <= now)
        .sort((a, b) => String(a.sendsAt).localeCompare(String(b.sendsAt)))
      : [];
    if (due.length && (!send || !appUrl)) {
      console.error('[dbu:sendCheckins] ' + due.length + ' due, but no mailer or no appUrl secret (tools/setup-signin.mjs): none sent');
      Outputs.sent = 0;
      Outputs.mailed = 0;
      Outputs.unsent = due.length;
      Outputs.done();
      return;
    }

    const key = secret('unsubscribeKey');
    const hex = (buf) => Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, '0')).join('');
    const unsubscribeFor = async (userId) => {
      if (!key) return '';
      const k = await crypto.subtle.importKey('raw', new TextEncoder().encode(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
      const sig = hex(await crypto.subtle.sign('HMAC', k, new TextEncoder().encode('dbu-unsubscribe:v1:' + userId)));
      return appUrl + '/unsubscribe?u=' + encodeURIComponent(userId) + '&s=' + sig;
    };

    for (const s of due) {
      // Re-read just before the claim: another run may have taken it since the list was made.
      const fresh = (await q('Step', { objectId: { equalTo: s.objectId } }))[0];
      if (!fresh || fresh.status !== 'scheduled' || fresh.shared !== true) continue;
      const learner = (await q('_User', { objectId: { equalTo: s.learner } }))[0];
      if (!learner) continue;
      const stamp = new Date().toISOString();
      await R.save(s.objectId, { status: 'sent', sentAt: stamp }, { className: 'Step' });

      const address = typeof learner.email === 'string' && learner.email.includes('@') ? learner.email : '';
      if (learner.emailOptOutAt || !address) {
        sent += 1;
      } else {
        // The coach is whoever writes to her; an email with no conversation yet says "your coach".
        const theirs = (await q('Message', { learner: { equalTo: s.learner } })).filter((m) => m.author !== s.learner)
          .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
        const coach = theirs.length ? (await q('_User', { objectId: { equalTo: theirs[0].author } }))[0] : null;
        const coachFirst = String((coach && coach.name) || '').split(' ')[0];
        const first = String(learner.name || '').split(' ')[0] || 'there';
        const form = s.form && Array.isArray(s.form.questions) ? s.form : { questions: [] };
        const minutes = Number.isInteger(form.minutes) ? form.minutes : 2;
        const n = form.questions.filter((x) => !x.condition).length || form.questions.length;
        const unsubscribe = await unsubscribeFor(learner.objectId);
        const who = coachFirst || 'Your coach';
        const text = [
          'Hello ' + first + ',',
          '',
          who + ' would like to know how things are going: ' + n + ' short question' + (n === 1 ? '' : 's') + ', about ' + minutes + ' minutes.',
          '',
          '"' + String(s.title || 'Check-in') + '"',
          'Answer here: ' + appUrl + '/checkin?step=' + encodeURIComponent(s.objectId),
          '',
          '--',
          'Replies to this email are not read. Your answers go straight to ' + (coachFirst || 'your coach') + ' when you send them.',
          unsubscribe ? 'Stop these emails: ' + unsubscribe : 'You can stop these emails on your Messages page.',
          'Your sign-in emails are not affected.'
        ].join('\n');
        let ok = false;
        let why = '';
        try {
          const res = await send({ to: address, subject: 'A ' + minutes + '-minute check-in' + (coachFirst ? ' from ' + coachFirst : ''), text });
          ok = !!(res && res.success);
          why = ok ? '' : String((res && res.error) || 'no answer');
        } catch (e) {
          why = String((e && e.message) || e);
        }
        if (!ok) {
          await R.save(s.objectId, { status: 'scheduled', sentAt: null }, { className: 'Step' });
          unsent += 1;
          console.error('[dbu:sendCheckins] send failed, left for the next run: ' + why.slice(0, 160).replace(/[^\s]+@[^\s]+/g, '<address>'));
          continue;
        }
        sent += 1;
        mailed += 1;
      }
      await R.create('Doorbell', { learner: s.learner, topic: 'plan' }, { acl: { [s.learner]: { read: true }, 'role:staff': { read: true } } });
    }
    if (due.length) console.log('[dbu:sendCheckins] due=' + due.length + ' sent=' + sent + ' mailed=' + mailed + ' unsent=' + unsent);
    Outputs.sent = sent;
    Outputs.mailed = mailed;
    Outputs.unsent = unsent;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:sendCheckins] ' + String((e && e.message) || e));
    Outputs.failed();
  }
})();
